<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';require __DIR__.'/discord-support.php';
if(PHP_SAPI!=='cli'||getenv('APP_ENV')!=='test'||getenv('DB_DATABASE')!=='levelingwiki_test')exit(1);
function dashCheck(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "OK dashboard : $label\n";}
$p=App\Services\Database::connect();$service=new App\Services\AdminDashboardService($p);$actor=['role'=>'admin','must_change_password'=>0];
$p->beginTransaction();
try{
$p->exec("UPDATE users SET is_active=0; UPDATE achievements SET archived_at=NOW(); UPDATE categories SET archived_at=NOW(); UPDATE guild_divisions SET archived_at=NOW(); UPDATE guild_milestones SET archived_at=NOW()");
$d=$service->overview($actor);dashCheck($d['summary']['members']===0&&$d['summary']['achievements']===0&&$d['summary']['declarations']===0&&$d['summary']['average']===0.0,'population vide sans division par zéro');dashCheck($d['ranking']===[]&&$d['most']===[]&&$d['categories']===[],'graphiques et classement vides');
$p->exec("INSERT INTO categories(slug,name) VALUES('dashboard-category','Catégorie statistique'),('dashboard-empty','Catégorie vide')");$cat=(int)$p->query("SELECT id FROM categories WHERE slug='dashboard-category'")->fetchColumn();
$ids=[];foreach([['member',1,'discord'],['admin',1,'discord'],['editor',1,'discord'],['member',0,'discord'],['admin',1,'local']] as $i=>[$role,$active,$provider]){
$p->prepare("INSERT INTO users(username,password_hash,role,auth_provider,is_active,must_change_password) VALUES(?,'unused',?,?,?,0)")->execute(['dash-'.$i,$role,$provider,$active]);$id=(int)$p->lastInsertId();$ids[]=$id;
if($provider==='discord')$p->prepare('INSERT INTO discord_identities(user_id,discord_user_id,display_name) VALUES(?,?,?)')->execute([$id,'10000000000000900'.$i,'Membre statistique '.$i]);}
$a=[];foreach([['Publié A','published',null],['Publié B','published',null],['Brouillon','draft',null],['Archive','published','2026-01-01 00:00:00']] as $i=>[$name,$status,$archive]){$p->prepare('INSERT INTO achievements(slug,name,category_id,publication_status,archived_at) VALUES(?,?,?,?,?)')->execute(['dash-a-'.$i,$name,$cat,$status,$archive]);$a[]=(int)$p->lastInsertId();}
$d=$service->overview($actor);dashCheck($d['summary']['members']===3,'admin et editor Discord inclus, compte désactivé et technique exclus');dashCheck($d['summary']['achievements']===2,'brouillons et archives exclus');dashCheck($d['summary']['average']===0.0&&count($d['ranking'])===3,'membres sans réussite inclus');
foreach([[$ids[0],$a[0]],[$ids[1],$a[0]],[$ids[3],$a[0]],[$ids[4],$a[0]],[$ids[0],$a[2]],[$ids[0],$a[3]]] as [$uid,$aid])$p->prepare("INSERT INTO personal_achievements(user_id,achievement_id,progress,obtained_at) VALUES(?,?,'obtained',NOW())")->execute([$uid,$aid]);
$p->exec("INSERT INTO guild_divisions(name,short_name,description,color,level) VALUES('Statistiques','STAT','','#AABBCC',120)");
$d=$service->overview($actor);dashCheck($d['summary']['declarations']===2&&$d['summary']['average']===33.3,'deux déclarations sur six possibles : 33,3 %');dashCheck((int)$d['ranking'][0]['position']===1&&(int)$d['ranking'][1]['position']===1&&(int)$d['ranking'][2]['position']===3,'égalité de rang 1,1,3');dashCheck($d['ranking'][0]['percent']===50.0,'pourcentage individuel');dashCheck((int)$d['most'][0]['total']===2&&(int)$d['least'][0]['total']===0,'effectifs hauts et bas, zéro inclus');
$byName=array_column($d['categories'],null,'name');dashCheck($byName['Catégorie statistique']['percent']===33.3&&$byName['Catégorie vide']['percent']===0.0,'catégories et catégories vides');dashCheck($d['summary']['divisions']===1&&$d['summary']['max_level']===120,'divisions archivées exclues');dashCheck((int)$d['attention']['unassigned_divisions']===1,'division sans responsable détectée');dashCheck((int)$d['attention']['unknown_rewards']===3,'récompenses inconnues actives détectées');
$p->exec("INSERT INTO guild_milestones(level,title,description) VALUES(998,'Incomplet','')");$mid=(int)$p->lastInsertId();dashCheck((int)$service->overview($actor)['attention']['incomplete_milestones']===1,'palier sans récompense détecté');
$p->prepare("INSERT INTO guild_milestone_rewards(milestone_id,distribution,visibility,description) VALUES(?,'unconfirmed','unknown','')")->execute([$mid]);dashCheck((int)$service->overview($actor)['attention']['incomplete_milestones']===1,'inconnue comptée une seule fois par palier');
$editor=$service->overview(['role'=>'editor']);dashCheck($editor['ranking']===[]&&!str_contains(json_encode($editor['activity']),'Membre statistique'),'éditeur sans classement nominatif ni activité personnelle');dashCheck(!str_contains(json_encode($d['ranking']),'discord_user_id')&&!str_contains(json_encode($d),'password_hash'),'aucun identifiant technique ou secret');
try{$service->overview(['role'=>'member']);dashCheck(false,'refus MEMBER');}catch(RuntimeException $e){dashCheck($e->getCode()===403,'service refuse MEMBER');}
}finally{$p->rollBack();}
seedDiscordRoles($p);$member=discordLogin('100000000000000981',['200000000000000001']);$editor=discordLogin('100000000000000982',['200000000000000001','200000000000000002']);$admin=discordLogin('100000000000000983',['200000000000000001','200000000000000003']);
dashCheck($member->request('/admin')['status']===403,'route refuse MEMBER');$body=$editor->request('/admin')['body'];dashCheck(str_contains($body,'Progression moyenne')&&str_contains($body,'réservé aux administrateurs'),'agrégats éditeur et restriction nominative');$body=$admin->request('/admin')['body'];dashCheck(str_contains($body,'dashboard-ranking')&&!str_contains($body,'password_hash'),'dashboard administrateur');
